def test_list_scope_namespaces_pager(transport_name: str = "grpc"):
    client = GkeHubClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport_name,
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(
        type(client.transport.list_scope_namespaces), "__call__"
    ) as call:
        # Set the response to a series of pages.
        call.side_effect = (
            service.ListScopeNamespacesResponse(
                scope_namespaces=[
                    fleet.Namespace(),
                    fleet.Namespace(),
                    fleet.Namespace(),
                ],
                next_page_token="abc",
            ),
            service.ListScopeNamespacesResponse(
                scope_namespaces=[],
                next_page_token="def",
            ),
            service.ListScopeNamespacesResponse(
                scope_namespaces=[
                    fleet.Namespace(),
                ],
                next_page_token="ghi",
            ),
            service.ListScopeNamespacesResponse(
                scope_namespaces=[
                    fleet.Namespace(),
                    fleet.Namespace(),
                ],
            ),
            RuntimeError,
        )

        expected_metadata = ()
        retry = retries.Retry()
        timeout = 5
        expected_metadata = tuple(expected_metadata) + (
            gapic_v1.routing_header.to_grpc_metadata((("parent", ""),)),
        )
        pager = client.list_scope_namespaces(request={}, retry=retry, timeout=timeout)

        assert pager._metadata == expected_metadata
        assert pager._retry == retry
        assert pager._timeout == timeout

        assert pager.next_page_token == "abc"
        assert str(pager).startswith(f"{pager.__class__.__name__}<")

        results = list(pager)
        assert len(results) == 6
        assert all(isinstance(i, fleet.Namespace) for i in results)


