def test_list_membership_bindings_pager(transport_name: str = "grpc"):
    client = GkeHubClient(
        credentials=ga_credentials.AnonymousCredentials(),
        transport=transport_name,
    )

    # Mock the actual call within the gRPC stub, and fake the request.
    with mock.patch.object(
        type(client.transport.list_membership_bindings), "__call__"
    ) as call:
        # Set the response to a series of pages.
        call.side_effect = (
            service.ListMembershipBindingsResponse(
                membership_bindings=[
                    fleet.MembershipBinding(),
                    fleet.MembershipBinding(),
                    fleet.MembershipBinding(),
                ],
                next_page_token="abc",
            ),
            service.ListMembershipBindingsResponse(
                membership_bindings=[],
                next_page_token="def",
            ),
            service.ListMembershipBindingsResponse(
                membership_bindings=[
                    fleet.MembershipBinding(),
                ],
                next_page_token="ghi",
            ),
            service.ListMembershipBindingsResponse(
                membership_bindings=[
                    fleet.MembershipBinding(),
                    fleet.MembershipBinding(),
                ],
            ),
            RuntimeError,
        )

        expected_metadata = ()
        retry = retries.Retry()
        timeout = 5
        expected_metadata = tuple(expected_metadata) + (
            gapic_v1.routing_header.to_grpc_metadata((("parent", ""),)),
        )
        pager = client.list_membership_bindings(
            request={}, retry=retry, timeout=timeout
        )

        assert pager._metadata == expected_metadata
        assert pager._retry == retry
        assert pager._timeout == timeout

        assert pager.next_page_token == "abc"
        assert str(pager).startswith(f"{pager.__class__.__name__}<")

        results = list(pager)
        assert len(results) == 6
        assert all(isinstance(i, fleet.MembershipBinding) for i in results)


