        response = (
            service.ListScopesResponse(
                scopes=[
                    fleet.Scope(),
                    fleet.Scope(),
                    fleet.Scope(),
                ],
                next_page_token="abc",
            ),
            service.ListScopesResponse(
                scopes=[],
                next_page_token="def",
            ),
            service.ListScopesResponse(
                scopes=[
                    fleet.Scope(),
                ],
                next_page_token="ghi",
            ),
            service.ListScopesResponse(
                scopes=[
                    fleet.Scope(),
                    fleet.Scope(),
                ],
            ),
        )
        # Two responses for two calls
